import os
import torch
import numpy as np
import random


class Config:
    """
    Centralized configuration for the RNA Degradation Prediction task.
    Implements the 'Gated-Fusion Wide-Stream Residual BiGRU' strategy parameters.
    """

    # =========================================================================
    # Paths & Directories
    # =========================================================================
    # Input Metadata (Parquet files generated by metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_FILE = os.path.join(METADATA_DIR, "train.parquet")
    VAL_FILE = os.path.join(METADATA_DIR, "val.parquet")
    TEST_FILE = os.path.join(METADATA_DIR, "test.parquet")

    # Working Directory for Caching and Models
    # Specific directory for this idea iteration
    WORKING_DIR = "./working/idea_31"

    # Model Checkpoint Path
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Submission Path
    # Ensuring the directory exists is handled in setup
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Data Specifications
    # =========================================================================
    SEQ_LEN = 107
    PRED_LEN = 68

    # The 3 scored targets for training and evaluation
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]
    NUM_TARGETS = len(TARGET_COLS)

    # Vocabularies
    # Nucleotides: A, G, C, U + Padding/Unknown if necessary (though data is clean)
    # We map A, G, C, U to indices 0, 1, 2, 3
    VOCAB_SIZE = 4

    # Loop Types: S, M, I, B, H, E, X
    LOOP_TYPES = ["S", "M", "I", "B", "H", "E", "X"]
    LOOP_VOCAB_SIZE = len(LOOP_TYPES)

    # =========================================================================
    # Model Hyperparameters
    # =========================================================================
    # Architecture: Gated-Fusion Wide-Stream Residual BiGRU

    # Input Embeddings
    EMBED_DIM = 128  # High-dimensional embeddings

    # Gated Fusion Stem
    FUSION_KERNEL_SIZE = 3  # Conv1D kernel size for local context

    # Backbone
    HIDDEN_DIM = 384  # Total width of the residual stream (BiGRU 192 per direction)
    N_LAYERS = 6  # Number of residual blocks

    # Regularization
    DROPOUT = 0.1  # Inter-layer dropout

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42

    # Optimization
    OPTIMIZER_NAME = "AdamW"
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4  # Low weight decay as per lessons
    BATCH_SIZE = 32  # Adjust based on VRAM (A100 40GB allows larger, but 32/64 is safe)
    EPOCHS = 20  # Fixed number of epochs

    # Scheduler
    # Cosine Annealing parameters
    T_MAX = EPOCHS  # T_max matches total epochs
    ETA_MIN = 1e-6  # Minimum learning rate

    # Gradient Clipping
    MAX_GRAD_NORM = 1.0

    # =========================================================================
    # Hardware
    # =========================================================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # For DataLoader

    @staticmethod
    def setup_environment():
        """
        Sets up the environment:
        1. Creates necessary directories.
        2. Sets random seeds for reproducibility.
        """
        # Create directories
        os.makedirs(Config.WORKING_DIR, exist_ok=True)
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)

        # Set seeds
        seed = Config.SEED
        random.seed(seed)
        os.environ["PYTHONHASHSEED"] = str(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

        print(
            f"Environment setup complete. Working dir: {Config.WORKING_DIR}, Device: {Config.DEVICE}"
        )


# Run setup immediately when config is imported to ensure directories exist
Config.setup_environment()
